using CoilManager.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace CoilManager.Persistence.Configurations;
public sealed class DispatchConfiguration:IEntityTypeConfiguration<Dispatch>{public void Configure(EntityTypeBuilder<Dispatch>b){b.ToTable("Dispatches","app");b.HasKey(x=>x.Id);b.HasIndex(x=>x.DispatchNumber).IsUnique();b.HasIndex(x=>x.PackingSlipNumber).IsUnique();b.HasIndex(x=>x.WorkOrderId);b.HasIndex(x=>x.Status);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ProductType).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.QuantityUnit).HasConversion<string>().HasMaxLength(20);foreach(var p in new[]{nameof(Dispatch.DispatchQuantity),nameof(Dispatch.NetWeight),nameof(Dispatch.GrossWeight),nameof(Dispatch.Thickness),nameof(Dispatch.Width)})b.Property(p).HasPrecision(18,3);b.Property(x=>x.CoreLossPerKg).HasPrecision(18,4);b.Property(x=>x.DispatchNumber).HasMaxLength(20);b.Property(x=>x.PackingSlipNumber).HasMaxLength(20);b.Property(x=>x.WorkOrderNumber).HasMaxLength(20);b.Property(x=>x.ShippingAddress).HasMaxLength(1000);b.Property(x=>x.RowVersion).IsRowVersion();b.HasOne(x=>x.WorkOrder).WithMany().HasForeignKey(x=>x.WorkOrderId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Packages).WithOne().HasForeignKey(x=>x.DispatchId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.InventorySources).WithOne().HasForeignKey(x=>x.DispatchId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Packages).UsePropertyAccessMode(PropertyAccessMode.Field);b.Navigation(x=>x.InventorySources).UsePropertyAccessMode(PropertyAccessMode.Field);}}
public sealed class DispatchPackageConfiguration:IEntityTypeConfiguration<DispatchPackage>{public void Configure(EntityTypeBuilder<DispatchPackage>b){b.ToTable("DispatchPackages","app");b.HasKey(x=>x.Id);b.HasIndex(x=>new{x.DispatchId,x.PackageNumber}).IsUnique();b.Property(x=>x.QuantityUnit).HasConversion<string>().HasMaxLength(20);foreach(var p in new[]{nameof(DispatchPackage.Quantity),nameof(DispatchPackage.NetWeight),nameof(DispatchPackage.GrossWeight),nameof(DispatchPackage.Length),nameof(DispatchPackage.Width),nameof(DispatchPackage.Height)})b.Property(p).HasPrecision(18,3);b.Property(x=>x.PackageNumber).HasMaxLength(30);b.Property(x=>x.Description).HasMaxLength(500);}}
public sealed class DispatchInventorySourceConfiguration:IEntityTypeConfiguration<DispatchInventorySource>{public void Configure(EntityTypeBuilder<DispatchInventorySource>b){b.ToTable("DispatchInventorySources","app");b.HasKey(x=>x.Id);b.HasIndex(x=>x.DispatchId);b.Property(x=>x.InventoryType).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.InventoryNumber).HasMaxLength(60);b.Property(x=>x.Width).HasPrecision(18,3);b.Property(x=>x.Quantity).HasPrecision(18,3);}}
